package vn.svframe.svframelib.api.crafting.recipes.vmp; import vn.svframe.svframelib.api.crafting.recipes.MythicRecipeStation; import java.util.*; public class MegaWorkbenchMapping extends VanillaInventoryMapping implements CustomInventoryCheck { public static final String MEGA_WORKBENCH="mwb"; public static MegaWorkbenchMapping MWB; private static final int[] MAIN={0,1,2,3,4,5,9,10,11,12,13,14,18,19,20,21,22,23,27,28,29,30,31,32,36,37,38,39,40,41,45,46,47,48,49,50}; private static final int[] EDGE={6,15,24,33,42,51,7,16,34,43,52,8,17,26,35,44,53}; public MegaWorkbenchMapping(){MWB=this;} public int getMainWidth(int r){return 6;} public int getMainHeight(int c){return 6;} public int getMainSlot(int x,int y){if(x<0||x>=6||y<0||y>=6)throw outOfBounds(x,y);return MAIN[y*6+x];} public int getMainInventoryStart(){return 0;} public int getMainInventoryWidth(){return 6;} public int getMainInventoryHeight(){return 6;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 25;} public int getResultInventoryStart(){return 25;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==25;} public int getSideWidth(String n,int r){throw sideInventoryException(n);} public int getSideHeight(String n,int c){throw sideInventoryException(n);} public int getSideSlot(String n,int x,int y){throw sideInventoryException(n);} public int getSideInventoryStart(String n){throw sideInventoryException(n);} public int getSideInventoryWidth(String n){throw sideInventoryException(n);} public int getSideInventoryHeight(String n){throw sideInventoryException(n);} public boolean mainIsResult(){return false;} public MythicRecipeStation getIntendedStation(){return MythicRecipeStation.WORKBENCH;} public String getIntendedInventory(){return "CHEST_54";} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>();} public boolean isTargetInventory(int size,String key){return size==54&&MEGA_WORKBENCH.equalsIgnoreCase(key);} public String getCustomStationKey(){return MEGA_WORKBENCH;} public static ArrayList<Integer> getEdgeSlots(){ArrayList<Integer> out=new ArrayList<>();for(int i:EDGE)out.add(i);return out;} }
